{
  "name": "SRM 拉取采购订单",
  "code": "srm_fetch_po",
  "description": "从客户 Mock SRM 门户拉取 PO",
  "entityType": "CUSTOMER",
  "category": "procurement",
  "status": "DRAFT",
  "version": "1.0.0",
  "inputSchema": [
    {
      "name": "po_no",
      "label": "PO 编号",
      "type": "string",
      "required": true
    }
  ],
  "businessSteps": [
    {
      "id": "login",
      "name": "登录门户"
    },
    {
      "id": "srm.search_po",
      "name": "搜索采购订单"
    },
    {
      "id": "srm.fetch_po",
      "name": "拉取 PO 详情"
    }
  ]
}

{
  "title": "Mock SRM 拉取 PO 成功",
  "taskType": "srm_fetch_po",
  "portalAccountId": "{{portal_account_id}}",
  "workflowBindingId": "{{workflow_binding_id}}",
  "entityType": "CUSTOMER",
  "erpEntityCode": "CUST-001",
  "erpEntityName": "示例客户 A",
  "priority": "NORMAL",
  "input": {
    "po_no": "PO-20260708-001"
  }
}

{
  "status": "WAITING_HUMAN",
  "error_code": "HUMAN_VERIFICATION_REQUIRED",
  "error_message": "Mock SRM requires CAPTCHA or MFA verification"
}

{
  "name": "autotask.task.create",
  "arguments": {
    "title": "MCP 创建 Mock SRM 任务",
    "taskType": "srm_fetch_po",
    "portalAccountId": "{{portal_account_id}}",
    "workflowBindingId": "{{workflow_binding_id}}",
    "entityType": "CUSTOMER",
    "erpEntityCode": "CUST-001",
    "erpEntityName": "示例客户 A",
    "input": {
      "po_no": "PO-20260708-001"
    }
  }
}
